INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('scyaewaid9ubaamkxkierscyae4oykf0', '2026-Q3', 'Set/2026 (T3)', '2026-09-21T17:42'::timestamptz, 'Gabriel de Oliveira Rodrigues', 'gabriel de oliveira rodrigues', 'PHARUS', 'Carlos Serafim', 7.0, 'Neutro', 8.0, NULL, NULL, NULL, NULL, NULL, 'Estagnado ou travado', 'Estou travado em alguma parte e preciso de ajuda', 'As estratégias são para altissima renda, não se aplicam a todos. E meu plano demorou bastante para ser montado, somente com o 3o gestor que o plano foi para a frente', 'Agilidade para trocar profissionais quando não estão atendendo; plano claro e adequado a renda de cada um. EX: eu tenho um patrimonio de ~500K, me apresentaram uma estrategia de 400 e pouco, o que comprometeria todo meu patrimonio e eu não teria nenhuma outra oportunidade em 3-4 anos.', NULL, 'Um plano claro sobre onde posso chegar em 1 ano, 3 e 5. Perspectiva das estratégias. Estratégias com tickets adequado a minha realidade.', 'Agora estou vendo progresso, mas os primeiros meses foram bem ruins.', NULL, NULL, 'typeform 2025-26', 'historico_typeform.csv', 'Typeform NPS', 'scyaewaid9ubaamkxkierscyae4oykf0', 'cadastro 2026-T3 (respondente) (0 dias)', 'base mecanismos') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategist