INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('p4s3eahtmf9t8gf4wfp4s3eaj3nc266o', '2026-Q3', 'Set/2026 (T3)', '2026-09-22T14:13'::timestamptz, 'João Paulo Sá Granja de Abreu', 'joao paulo sa granja de abreu', 'PHARUS', 'Rodrigo Amorim', 7.0, 'Neutro', 8.0, NULL, NULL, NULL, NULL, NULL, 'Em progresso, mas com dúvidas', 'Entendi o método, mas ainda não implementei o suficiente', 'No início as ideias pareciam fazer sentido, porém ainda não vi uma evolução concreta, nem os projetos e as ideias sairem do papel', 'Creio propiciar o retorno divulgado nos portifólio de investimentos que a QuartaVia possui, não havendo notícias, por exemplo, de como estão os R$ 10.000,00 aplicados no fundo de investimento em 24/04 ou o valor disponibilizado para compra em leilão.', NULL, 'Ter um feedback de como está a evolução', 'Não', NULL, NULL, 'typeform 2025-26', 'historico_typeform.csv', 'Typeform NPS', 'p4s3eahtmf9t8gf4wfp4s3eaj3nc266o', 'cadastro 2026-T3 (respondente) (0 dias)', 'base mecanismos') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado