INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('6rt6k7j0dwnv7il7i6rt6kglsw4j7f3y', '2026-Q3', 'Set/2026 (T3)', '2026-09-22T14:13'::timestamptz, 'Ronaldo Peixoto Bella', 'ronaldo peixoto bella', 'PHARUS', 'Thiago Henrique Trova', 0.0, 'Detrator', 10.0, NULL, NULL, NULL, NULL, NULL, 'Desacreditei do método', 'Perdi o vínculo com o projeto e preciso retomar', 'Na maioria das ofertas a documentação detalhada não foi enviada tempo hábil pra análise. Se foca muito o comercial, mas pouco a parte técnica das ideias de investimentos. Afinal gastei 20 mil e não vou ter feito nada, eu cancelaria antes do prazo e possível. Nada sobre o planejador que me acompanhou, ele também recebia as coisas em cima da hora.', 'Ser muiito mais didático e explicativo com as ofertas. Quando tudo vai bem, tudo certo, mas o diabo mora nos detalhes, e quando as coisas dão ruim precisamos ter clareza de como serão resolvidas, e isso se define previamente.', NULL, 'Não continuarei.', 'Gostaria de cancelar antes do prazo se possível, deixando de pagar o que falta', NULL, NULL, 'typeform 2025-26', 'historico_typeform.csv', 'Typeform NPS', '6rt6k7j0dwnv7il7i6rt6kglsw4j7f3y', 'cadastro 2026-T3 (respondente) (0 dias)', 'base mecanismos') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estr